{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://mdbase.dev/contracts/schemas/mdbase.person/1.0.0.schema.json",
  "title": "Person",
  "description": "A portable person reference with editable account identity associations. Not an authentication or access-control assertion.",
  "type": "object",
  "required": ["id", "name"],
  "properties": {
    "id": {
      "type": "string",
      "pattern": "\\S",
      "description": "Stable person identifier used by references such as task assignments; independent of file path, name, account, and membership."
    },
    "name": {
      "type": "string",
      "pattern": "\\S",
      "description": "Collection-owned display name, not a verified account name."
    },
    "identities": {
      "type": "array",
      "uniqueItems": true,
      "description": "Editable identity associations. Missing or empty means this person has no linked account. Match issuer and subject exactly; never match by email or name.",
      "items": {
        "type": "object",
        "required": ["issuer", "subject"],
        "properties": {
          "issuer": {
            "type": "string",
            "format": "uri",
            "pattern": "^https?://",
            "description": "Stable issuer URL supplied by the identity service. Copy exactly; do not derive from a collection authority or relay URL."
          },
          "subject": {
            "type": "string",
            "pattern": "\\S",
            "description": "Opaque, case-sensitive, account-wide identifier supplied by the issuer. Not an email, membership ID, or credential."
          }
        },
        "additionalProperties": false
      }
    }
  },
  "additionalProperties": false
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://mdbase.dev/contracts/schemas/mdbase.contact/1.0.0.schema.json",
  "title": "Contact",
  "description": "A compact application-facing contact view.",
  "type": "object",
  "required": ["name"],
  "properties": {
    "name": {
      "type": "string",
      "minLength": 1,
      "description": "The name applications should use when presenting this contact."
    },
    "kind": {
      "type": "string",
      "enum": ["individual", "organisation", "group"],
      "description": "The broad kind of contact when the collection distinguishes it."
    },
    "primary_email": {
      "type": "string",
      "format": "email",
      "description": "The preferred email address for this contact."
    },
    "primary_phone": {
      "type": "string",
      "minLength": 1,
      "description": "The preferred telephone number for this contact."
    },
    "organisation": {
      "type": "string",
      "minLength": 1,
      "description": "The organisation most closely associated with this contact."
    },
    "birthday": {
      "type": "string",
      "format": "date",
      "description": "The contact's birthday when known."
    }
  },
  "additionalProperties": false
}
